import unittest
from exports import export_tickets


class ExportTicketsTests(unittest.TestCase):
    def test_csv_contract(self):
        rows = [{
            "owner": "Lin",
            "summary": "修复;导出\n格式",
            "ticket_id": 42,
            "extra": "ignored",
        }]
        self.assertEqual(
            export_tickets(rows),
            "\ufeffticket_id;summary;owner\r\n42;\"修复;导出\n格式\";Lin\r\n".encode("utf-8"),
        )

    def test_empty_rows(self):
        self.assertEqual(
            export_tickets([]),
            "\ufeffticket_id;summary;owner\r\n".encode("utf-8"),
        )


if __name__ == "__main__":
    unittest.main()
